#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n - 2; placed++) {
        // Find where (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        // We want to move element from pos to placed
        // Operation 1: move element to position 'placed' directly if possible
        // Try: x = placed, y = n - pos. Then suffix starts at pos, prefix is [0..placed-1]
        // After: [pos..n-1] [placed..pos-1] [0..placed-1]
        // Element at pos goes to position 0... we want it at 'placed'

        // Strategy: first move element to last position (n-1)
        if (pos < n - 1) {
            int x = pos + 1;
            int y = n - 1 - pos;
            // x + y = n - need middle non-empty, so x+y < n required
            // x+y = pos+1+n-1-pos = n, too big. Use y = n-2-pos if possible
            // Actually let's move it differently: x=1, y=n-1-pos puts suffix [pos+1..n-1] at front
            // Instead: just bring it to position n-1
            if (pos + 1 < n && n - 1 - pos > 0 && (pos + 1) + (n - 1 - pos) < n) {
                // impossible since sum = n
            }
            // Use x = pos+1, y = n-pos-2 (leave one element as middle before suffix)
            int yy = n - pos - 2;
            if (pos + 1 > 0 && yy > 0 && pos + 1 + yy < n) {
                ops.push_back({pos + 1, yy});
                apply(p, pos + 1, yy);
                pos = n - 1 - yy; // element moves to end of new prefix = position n - 1 - ... 
                // Just re-find
                for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
            }
        }
        if (pos == placed) continue;
        // Now place it: x = placed, y = n - pos if valid, or other combo
        // Try all valid (x,y) to see which one places element correctly
        bool done = false;
        for (int x = 1; x <= n-2 && !done; x++) {
            for (int y = 1; x + y < n && !done; y++) {
                // element at pos: after op, where does it go?
                int newpos;
                if (pos >= n - y) newpos = pos - (n - y); // in suffix -> goes to front
                else if (pos >= x) newpos = y + (pos - x); // in middle -> shifted
                else newpos = y + (n - y - x) + pos; // in prefix -> goes to end
                if (newpos == placed) {
                    ops.push_back({x, y});
                    apply(p, x, y);
                    done = true;
                }
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
